grep -n 'estimate_cost_usd' -B6 -A3 backend/tracepoint/llm/gateway.py | sed -n 1,40p; cd backend && .venv/bin/python - <<'EOF'
from tracepoint.core.settings import get_settings
from tracepoint.llm.gateway import make_provider
s = get_settings()
print("base_url repr:", repr(s.openai_base_url), "| temp:", s.llm_temperature)
p = make_provider(s)
schema = {"type": "object", "properties": {"ok": {"type": "boolean"}}, "required": ["ok"], "additionalProperties": False}
for m in (s.openai_model, s.openai_model_bulk):
    try:
        r = p.complete(model=m, system="Reply with JSON.", user="Set ok to true.", schema=schema,
                       schema_name="ping", temperature=s.llm_temperature, max_output_tokens=200, timeout=60)
        print(m, "->", r.model, r.text, r.input_tokens, r.cached_tokens, r.output_tokens, r.finish_reason)
    except Exception as e:
        print(m, "FAILED:", type(e).__name__, str(e)[:400])
try:
    e = p._client.embeddings.create(model=s.embedding_model, input="ping")
    print(s.embedding_model, "->", e.model, len(e.data[0].embedding), e.usage.total_tokens)
except Exception as ex:
    print("embedding FAILED:", type(ex).__name__, str(ex)[:400])
EOF

